 def src(title,url,locator,kind='原典／研究入口'):
  return dict(title=title,url=url,locator=locator,kind=kind,note='本文为本站编写的导读；具体作品的章节、成文过程与现代解释分别阅读，不以概述替代原文。')
 def sep(slug,title):return src('斯坦福哲学百科：'+title,'https://plato.stanford.edu/entries/'+slug+'/','文章正文及原典书目','学术百科与研究书目')
 pre=sep('presocratics','前苏格拉底哲学');plato=sep('plato','柏拉图');arist=sep('aristotle','亚里士多德');socr=sep('socrates','苏格拉底')
 stoic=sep('stoicism','斯多亚学派');epic=src('伊壁鸠鲁《致美诺伊克斯书》','https://classics.mit.edu/Epicurus/menoec.html','幸福、欲望、死亡与审慎的论述','古代文本旧英译')
 sceptic=sep('skepticism-ancient','古代怀疑论');plotinus=sep('plotinus','普罗提诺');porph=sep('porphyry','波菲利')
 apology=src('柏拉图《申辩篇》','https://classics.mit.edu/Plato/apology.html','苏格拉底的辩护及作者的叙述','古代对话旧英译')
 ethics=src('亚里士多德《尼各马可伦理学》','https://classics.mit.edu/Aristotle/nicomachaen.html','第一、二、六卷：幸福、德性、实践智慧','古代文本旧英译')
 arabic=sep('arabic-islamic-greek','阿拉伯语哲学中的希腊来源');latin=sep('arabic-islamic-influence','阿拉伯语哲学与拉丁世界');medieval=sep('medieval-philosophy','中世纪哲学')
 human=src('国会图书馆：文艺复兴人文主义','https://www.loc.gov/exhibits/vatican/humanism.html','古典语言、修辞、文献与宗教研究的馆藏示例','馆藏展览与研究说明')
 ficino=sep('ficino','费奇诺');renarist=sep('aristotelianism-renaissance','文艺复兴时期亚里士多德主义');pico=sep('pico-della-mirandola','皮科');erasmus=sep('erasmus','伊拉斯谟')
