 events=[];early=[];traditions=[]
 def event(id,year,title,place,coords,people,topic,a,b,c,d,refs,end=None,links=None,image=None):
  e=dict(id='culture-'+id,side='west',culture=True,year=year,endYear=end or year,title=title,place=place,coordinates=dict(lon=coords[0],lat=coords[1]),people=people.split('、'),topic=topic,summary=b,sections=sections(a,b,c,d),dateKind='文化史 · '+('约年／长时段过程' if end else '编年节点；见史料提示'),sources=refs,eventIds=links or [],relatedEventIds=[],imageId=image)
  events.append(e)
 def before(id,span,title,people,a,b,c,d,refs):
  early.append(dict(id='prehistory-'+id,year=span[0],endYear=span[1],range=span,title=title,people=people.split('、'),sections=sections(a,b,c,d),sources=refs,eventIds=[],kind='哲学前史；年代为约略活动或发展区间，不接入公元主年轴'))
 before('miletus',[-600,-525],'米利都：自然的根源与解释方式','泰勒斯、阿那克西曼德、阿那克西美尼','爱奥尼亚的城邦、航海和知识交流，为讨论天地、生命与秩序提供环境。现存资料大多不是他们完整保存的原著。','这些思想者尝试用水、无定者或气等概念说明世界根源，不仅叙述神的谱系，也寻求可以争论的解释。各人的观点不能混成同一理论。','后来的希腊作者把他们放在哲学的起源中，这一分类影响了哲学史书写；自然研究、宗教与政治在当时仍有交叉。','前六世纪是约略范围，不是“哲学在前600年某日诞生”。许多思想经亚里士多德及更晚作者转述，须区分残篇与后世解释。',[pre])
 before('pythagoras',[-530,-400],'毕达哥拉斯传统：数、秩序与生活','毕达哥拉斯、早期毕达哥拉斯学派','南意大利希腊城市形成不同思想与共同生活网络，学派同时涉及宗教实践、政治和教育。','数与比例被用来思考和谐及宇宙秩序，灵魂与生活规则也进入相关传统；不能把全部后世数学发现都归给一位创始者。','数学与哲学的关系后来影响柏拉图及多种宇宙论，但具体承继需要逐项核对，不是一条毫无分歧的直线。','毕达哥拉斯本人没有可靠保存的著作，传记与学派材料跨越许多年代。“毕达哥拉斯定理”名称不是个人首创权的完整历史证明。',[sep('pythagoras','毕达哥拉斯')])
 before('heraclitus',[-500,-475],'赫拉克利特：变化与共同的逻各斯','赫拉克利特','城邦秩序、知识和人的判断，成为前五世纪思想讨论的一部分；他对多数人的理解能力持尖锐批评。','变化、对立中的联系及逻各斯，是阅读其残篇的重要线索。并非一切变化都等于毫无秩序，解释也不能只靠一句河流名言。','逻各斯一词后来在不同哲学、犹太与基督徒文本中出现，含义和问题各异；词形相同不等于所有作者提出完全相同的教义。','残篇依后世作者引述保存，断章和翻译选择都会影响理解。不把常见格言自动当作他原文的逐字完整句子。',[sep('heraclitus','赫拉克利特')])
 before('parmenides',[-480,-450],'巴门尼德：存在、思维与论证','巴门尼德、芝诺','关于变化、感觉与可靠知识的争论，促使思想者更明确地说明论证的前提和结论。诗的形式与逻辑探问在此并存。','巴门尼德讨论“是”与“不可能不是”等道路，芝诺的悖论挑战关于多与运动的直观判断；他们并不是简单说日常经验毫无意义。','这些难题促使后来的多元论者、原子论者及柏拉图重新思考存在和变化可以如何同时说明。','文本残缺，诗中不同部分怎样关联有多种解释；不把现代逻辑或物理学的答案直接当成古代作者已经给出的理论。',[sep('parmenides','巴门尼德')])
 before('pluralists',[-450,-400],'多元根源与原子：解释变化的不同方案','恩培多克勒、阿那克萨戈拉、德谟克利特','前五世纪的思想者面对同一个难题：若存在不能从无产生，眼前的生灭、差异和秩序如何解释？不同城市与作者给出不同方案。','根、混合与分离、心灵或原子与虚空等概念，分别说明事物的构成和运动。这里并没有一套所有人共同接受的自然科学体系。','这些理论后来成为伦理学、医学和哲学争论的资源；古代原子论与现代实验、数学物理的原子理论需分别理解。','材料来自残篇与后世见证，作者间的先后、影响和术语对应仍有研究争论，不以一个人的名字替代整个发展过程。',[pre,sep('democritus','德谟克利特')])
 before('sophists',[-450,-400],'智者与城邦教育：语言、规范和说服','普罗泰戈拉、高尔吉亚','雅典等城邦的公共生活需要演说、辩论和教育，法律、习俗与自然之间的关系因此进入讨论。','被称为智者的一些教师收费传授修辞和其他知识，提出关于人、语言和政治秩序的不同观点，并不构成统一教义的组织。','苏格拉底和柏拉图与这些人的论辩，推动知识、德性和说服之间的界限成为哲学问题。','不能只凭柏拉图作品中的论敌形象就概括所有智者；也不把“人是尺度”直接当作整个文艺复兴已经在古代完成的宣言。',[sep('sophists','智者')])
 before('socrates',[-399,-399],'苏格拉底受审：如何检验一种生活？','苏格拉底、柏拉图、色诺芬','苏格拉底在雅典公共交谈中追问德性和知识，处于城邦战争、政治冲突及教育争议之后的具体环境。','前399年的审判和死亡，使关于敬神、教育、公民义务与个人良知的问题进入不同作者的叙述。他本人没有留下著作。','后继者以多种方式发展苏格拉底形象，不能只把一种对话中的声音当作唯一可恢复的历史本人。','柏拉图的《申辩篇》、色诺芬的记述及喜剧材料各有体裁与立场；前399年是事件节点，思想发展并非只发生在这一年。',[apology,socr])
 before('academy',[-387,-347],'柏拉图与学园：知识、善与政治','柏拉图、学园成员','苏格拉底之后，哲学教育、数学探究与城邦政治的关系成为新的组织和写作问题，柏拉图以对话而非教科书式体系展开讨论。','学园约于前四世纪早期形成；理念、灵魂、正义和善等问题在不同对话中以不同方式呈现，不能把每位对话人物的发言都当作作者最终结论。','学园传统与后来的中期、晚期柏拉图主义有联系也有变化；文艺复兴读者又经翻译和注释重新组织这些作品。','常用前387年前后为学园成立约年。柏拉图生卒及部分对话的先后有讨论，不凭近代教材画出完全确定的成长阶段。',[plato])
 before('lyceum',[-335,-322],'亚里士多德与吕克昂：分门研究与德性','亚里士多德、泰奥弗拉斯托斯','亚里士多德曾在学园学习，又在不同地方研究和教学，不能仅被概括为反对柏拉图的学生。','约前335年在雅典形成的教学活动联系逻辑、自然、生物、伦理、政治和诗学。德性、因果和论证在各领域有不同用途。','其著作后来经希腊语注释及叙利亚语、阿拉伯语、希伯来语和拉丁语阅读发展出多种传统，传播并非只有一次重新发现。','现存许多文本像教学材料，题名、整理与编排有复杂历史；不要把现代学科边界原样套回前四世纪。',[arist,ethics])
 before('garden',[-306,-270],'伊壁鸠鲁的花园：快乐、友谊与有限欲望','伊壁鸠鲁、花园群体','城邦世界与希腊化王国的变动，使个人如何安顿生活成为重要问题；学派也借友谊、书信和共同实践维持联系。','花园传统把免除身体痛苦和心灵扰乱、审慎选择欲望及友谊置于伦理生活中。原子论用于解释自然并减轻恐惧。','它与斯多亚派、怀疑派对幸福和判断的回答不同，后来也受到基督徒及其他作者的批评、吸收或重述。','“快乐”不能直接译成放纵享乐。前306年通常用作雅典花园建立的约略节点，不能代替整个学派后来的复杂历史。',[epic,sep('epicurus','伊壁鸠鲁')])
 before('stoa',[-300,-200],'斯多亚学派：判断、德性与宇宙秩序','芝诺、克里安西、克律西波','早期斯多亚教学形成于希腊化雅典，研究伦理、逻辑和自然三方面，各部分并非彼此无关。','学派主张德性在善的生活中具有根本地位，并讨论人的判断、情感与普遍秩序。后来罗马作者以新的题材和体裁表达其思想。','塞涅卡、爱比克泰德和马可·奥勒留是后续重要作者，但他们不是早期创始者的逐字复述；基督徒与斯多亚的关系也因作者而异。','约前300年表示形成阶段，不是精确建制日。日常所说的“坚忍”不足以概括学派，节制情绪也不等于对他人冷漠。',[stoic])
 before('skepticism',[-300,-80],'怀疑传统：暂缓判断与学园的争论','皮浪、阿尔凯西劳、卡尔内阿德','知识和幸福的论辩不仅产生肯定性理论，也促使一些作者追问判断可以凭什么获得可靠性。','皮浪传统与学园怀疑主义具有不同背景，暂缓判断、论辩双方及可接受判断等问题并不只有一种共同答案。','后世塞克斯都保存的论证和文艺复兴的再阅读，使古代怀疑论参与早期近代知识论争论。','不要把怀疑论简化为“任何事都不相信”，也不能把皮浪的生平与数百年后体系化的文本当作同一层材料。',[sceptic])
 before('cicero',[-45,-44],'西塞罗：把希腊论辩转入拉丁语','西塞罗','罗马共和国晚期的政治和个人处境促成大量哲学写作，拉丁语词汇需要承担希腊讨论中的概念区分。','《论善恶的终极》《图斯库卢姆谈论》等著作借对话、介绍和批评展示不同学派，为拉丁读者提供伦理与知识问题的语言。','他的散文、修辞与道德讨论后来成为人文主义教育的重要资源；文艺复兴不是从零开始接触全部希腊思想。','前45—44年标一批著作的写作阶段，不是西塞罗首次学习哲学的时间，也不表示他只是没有选择地翻译希腊作者。',[sep('cicero','西塞罗')])
 # Dated cultural nodes remain within the existing AD timeline.
 event('greek-roman',30,'新约时代的哲学与城市教育背景','雅典、地中海城市',(23.73,37.98),'希腊语教师、不同学派与城市读者','哲学与思想','罗马统治下的地中海保存多种希腊哲学和教育传统，城市居民的语言、社会身份与受教育机会并不相同。','这是约公元30年的背景截面：斯多亚、伊壁鸠鲁、柏拉图与亚里士多德传统持续被讲授、争论和调整。','基督徒、犹太作者与这些思想相遇时既借用词汇，也提出分歧；不能因出现同一个术语便认定教义完全相同。','本条是时代背景，不是30年发生了一次哲学建国。希腊哲学前史另列，避免把公元前人物塞进新约编年。',[stoic,epic,plato])
 event('philo',40,'斐洛：犹太经文与希腊哲学解释','亚历山大里亚',(29.92,31.20),'亚历山大里亚的斐洛','哲学与思想','希腊语犹太经文与城市哲学教育相遇，为讨论创造、律法和德性提供多种解释资源。','斐洛运用寓意等方式解释摩西传统，使用柏拉图、斯多亚等思想资源，但有自己的经文问题与宗教立场。','这补充新约时代多语言思想环境，不能把希腊哲学与圣经之间的关系说成只有基督徒后来才第一次处理。','约40年为其成熟活动的阅读入口，不是所有著作的完成年。逻各斯等词在斐洛、不同哲学家与约翰文本中的含义须分别讨论。',[sep('philo','斐洛')])
 event('areopagus',51,'雅典的哲学听众与使徒行传叙事','雅典',(23.73,37.98),'保罗、伊壁鸠鲁派与斯多亚派听众','哲学与思想','使徒行传把雅典写成存在不同祭祀、公共讨论和学派听众的城市，叙事也从作者的信仰立场组织这些人物。','亚略巴古段落呈现保罗与不同听众围绕神、世界和复活的接触及分歧，为读者提供哲学与宗教交往的具体场景。','可以比较言说方式、诗句引用和听众反应，但不能仅凭这一段推导所有哲学家或所有基督徒的统一态度。','51年为本站推定编年；作者没有给出这次讲论的公历日期。前史中的学派起源与一世纪听众不同。',[src('使徒行传17:16—34','https://www.biblegateway.com/passage/?search=Acts+17:16-34&version=CUVS','雅典与亚略巴古','圣经经文')],links=['acts-039'])
 event('seneca',63,'塞涅卡的书信与罗马斯多亚伦理','罗马',(12.48,41.90),'塞涅卡、卢基利乌斯','哲学与思想','罗马政治、友谊和私人修养共同构成哲学写作环境，伦理问题不是仅在正式学校里讨论。','《致卢基利乌斯书信》等文本以时间、死亡、财富、德性和自我训练为题，组织读者对生活的检视。','这些文本后世在拉丁教育和基督徒阅读中被选择性接纳，影响不表示不同信仰之间没有重要差异。','约63—65年表示晚期书信写作阶段。后世托名的塞涅卡—保罗书信不能当作两人实际通信的确证。',[sep('seneca','塞涅卡')],end=65)
 event('epictetus',125,'爱比克泰德：可由自己负责的判断','尼科波利斯',(20.73,39.01),'爱比克泰德、阿里安','哲学与思想','奴隶经历、帝国社会和哲学教学构成爱比克泰德思想的背景，他的教导主要经阿里安保存。','《谈话录》和《手册》区分判断、选择与外部遭遇，强调德性及与他人的责任，不是保证人可以控制所有事件。','“可以负责什么”的问题后来进入多种修养传统，但现代心理工具与古代自然、神学和伦理的整体系统不能完全等同。','约125年为教学及记录的阅读节点，文本成文有范围讨论；现存语言也经过记录者的选择。',[src('爱比克泰德《谈话录》','https://classics.mit.edu/Epictetus/discourses.html','阿里安所记各卷','古代文本旧英译'),stoic],end=135)
 event('marcus',170,'马可·奥勒留：皇帝的自我劝诫','罗马帝国边疆',(16.37,48.21),'马可·奥勒留','哲学与思想','帝国统治、军事压力与个人修养在这位皇帝的生平中相遇；私人笔记不是行政政策的完整说明。','后称《沉思录》的希腊语笔记反复讨论判断、死亡、职责和共同生活，具有对自己说话的训练性质。','它成为后世斯多亚阅读的重要资源，但不能由书中的理想自我直接推断其统治下所有居民都得到同样待遇。','约170—180年标写作的常用范围，地点及各卷成文顺序未全确定；现代书名和排印也不是作者亲自出版的书。',[src('马可·奥勒留《沉思录》','https://classics.mit.edu/Antoninus/meditations.html','各卷自我劝诫','古代文本旧英译')],end=180)
 event('plotinus',244,'普罗提诺在罗马教学与晚期柏拉图主义','罗马',(12.48,41.90),'普罗提诺、罗马求学群体','哲学与思想','晚期古代的哲学群体连接不同城市、教师与读者。柏拉图和亚里士多德著作在持续注释中被重新解释。','普罗提诺来到罗马展开教学，后来著述讨论太一、理智、灵魂及人的归返，形成深远影响的解释方案。','其思想经波菲利编排及不同语言的阅读进入后续传统，但不能把全部基督徒神学等同于改写普罗提诺。','244年为来罗马教学的节点，写作主要开始于后期。所谓“新柏拉图主义”是后世分类，不是他自用的现代式学派招牌。',[plotinus])
 event('enneads',301,'波菲利编排《九章集》','罗马及地中海学术网络',(12.48,41.90),'波菲利、普罗提诺','文本与科技','教师离世后，保存、编排和解释讲授材料成为后继者的工作，文集的结构也会改变读者理解。','波菲利约于此时整理普罗提诺著作，按六组九篇编排，并撰传记，为后人阅读提供重要框架。','这说明思想传承不仅依赖创始者，也依赖编辑、传抄与书目安排。原写作顺序和后来的主题顺序应分开。','301年前后是常见编订约年，不是全部论文的原始写作年。现存文集还经历了后续抄本和校勘过程。',[porph,plotinus])
 event('augustine-platonists',386,'奥古斯丁阅读“柏拉图派书籍”','米兰',(9.19,45.46),'奥古斯丁、拉丁译者与友人','哲学与思想','米兰的宗教与教育网络连接拉丁经典、基督徒解释和哲学著作，个人阅读又处于生平选择之中。','《忏悔录》回顾对柏拉图派书籍的阅读及其与基督信仰的关系，既说明获得的概念资源，也写出作者认为仍需补充的方面。','拉丁翻译和具体交往参与这一过程。接受哲学并非把一个完整体系原封不动转为教义，而是重新提出问题和区分。','386年与归信阶段相关；《忏悔录》写于后来，是经过神学和文学组织的回顾，不是386年的即时日记。',[src('奥古斯丁《忏悔录》','https://www.newadvent.org/fathers/110107.htm','第七卷，柏拉图派书籍与解释','古代文本旧英译')])
 event('athens529',529,'雅典哲学教学与皇帝的限制','雅典',(23.73,37.98),'雅典教师、查士丁尼','教育与制度','晚期古代的哲学教学与宗教政治相互影响，不同城市的学校和教师也并非采取同样立场。','529年前后的帝国措施影响雅典哲学教师的活动，相关人员随后有迁移经历。此事不等于所有希腊哲学研究同年终结。','拜占庭的教育、注释和文本传抄，以及其他语言传统继续发展；不能用一个关闭故事解释其后全部知识史。','具体命令、适用范围与学校连续性有研究讨论。把529称为“古代哲学的死亡日”会掩盖后续活动。',[sep('damascius','达马斯基奥斯'),medieval])
 event('philoponus',529,'斐洛波诺斯批评世界永恒论','亚历山大里亚',(29.92,31.20),'约翰·斐洛波诺斯、普罗克洛斯的读者','哲学与思想','亚历山大里亚的注释传统把亚里士多德、柏拉图及其他作者放进教学论辩，宗教立场与论证工作同时存在。','斐洛波诺斯在反对普罗克洛斯的著作中批评世界永恒论，后来也对亚里士多德自然学提出多方面挑战。','这显示晚期基督徒作者不只是复制古典权威，也能在既有语言和论证框架中提出批评，并被不同语言传统继续阅读。','529年关联特定著作，不是其全部思想或现代物理学在此诞生。其基督论处境与自然哲学论证需分别分析。',[sep('philoponus','斐洛波诺斯')])
 event('translations',800,'希腊语、叙利亚语与阿拉伯语的翻译网络','巴格达及西亚城市',(44.37,33.32),'译者、医师、学者与赞助者','文本与科技','古典知识的跨语言流动依赖多种社群、手稿、学校与政治赞助。拜占庭的希腊语传统并未因此停止。','八至十世纪的翻译、校订和注释把逻辑、医学、数学及哲学著作带入阿拉伯语讨论，译者常在不同语言间比勘。','后来拉丁与希伯来语读者接触的是经过选择、解释与发展的作品，不是一个没有变化的希腊思想包裹。','800年是长过程的阅读起点，不把全部翻译归给同一机构，也不称为只靠一条道路把失去的西方知识送回欧洲。',[arabic],end=1000)
 event('kindi',850,'肯迪：用阿拉伯语重述哲学问题','巴格达',(44.37,33.32),'肯迪、译者与宫廷学者','哲学与思想','译介提供新的概念资源，阿拉伯语作者也面对自身关于原因、理智、宗教与自然的讨论。','肯迪及其圈子的研究联系哲学、数学与其他知识，尝试组织不同希腊来源，并提出自己的论证。','阿拉伯语哲学不是纯粹的搬运工作；后来的作者会继续批评、改造和选择这些方案。','约850年标成熟活动阶段，不是所有作品的写作日。特定文本的希腊来源与阿拉伯语改写需逐篇研究。',[sep('al-kindi','肯迪')])
 event('avicenna',1027,'伊本·西那《治疗论》的哲学体系','哈马丹、伊斯法罕',(51.67,32.65),'伊本·西那','哲学与思想','学术活动与不同政治中心、个人任职和求学网络相连，哲学研究不只发生于一座固定学校。','《治疗论》以逻辑、自然、数学和形而上学组织知识，对存在、必然与可能、灵魂和认识作出自己的系统论证。','作品及其解释进入拉丁、希伯来语等传统，对中世纪和后来哲学产生影响，并不只是亚里士多德的摘要。','约1027年是常见成书节点之一，部分写作跨越更长过程。《治疗论》是哲学百科，不要仅凭题名把它误当医学专著。',[sep('ibn-sina','伊本·西那')])
 event('toledo',1150,'托莱多与多地的拉丁翻译活动','托莱多及地中海城市',(-4.03,39.86),'克雷莫纳的杰拉德、不同语言协作者','文本与科技','伊比利亚与意大利等地提供接触阿拉伯语和希腊语文本的条件，翻译工作依赖具体人员合作而非一个统一的欧洲计划。','十二世纪译者将自然学、逻辑、医学和数学材料转入拉丁语，注释与术语选择也随之进入新的课程和争论。','把它与直接从希腊语翻译的活动并读，才能看到多条通道；犹太和基督徒协作者也有各自身份及工作。','1150年是世纪中段的阅读节点，不是一个正式“托莱多翻译学院”在此年统一成立的断言。',[latin,medieval],end=1200)
 event('abelard',1120,'阿伯拉尔的问答与权威文本问题','巴黎',(2.35,48.86),'彼得·阿伯拉尔、学生与论敌','哲学与思想','学校教学以经文、教父及逻辑训练展开，传统中的不同表述需要解释，而非假定任何两句话都没有张力。','《是与否》等作品并列看似冲突的权威说法，促使读者借语境、词义和推理处理问题。','这为理解经院教学的问题组织提供入口，也显示批判性阅读并非到文艺复兴才突然出现。','约1120年为写作阶段的约略入口；不同修订和作品之间有差异，不把后来的大学制度全部提前赋予这时的学校。',[sep('abelard','阿伯拉尔')],end=1140)
 event('averroes',1180,'伊本·鲁世德的亚里士多德注释','科尔多瓦、马拉喀什',(-4.78,37.89),'伊本·鲁世德','哲学与思想','安达卢斯的法律、医学、宗教与哲学讨论，为研究古典著作提供具体环境；作者同时具有多重工作身份。','伊本·鲁世德写作不同层次的亚里士多德注释，并讨论哲学论证与宗教解释的关系，不只是把信仰与理性简单分离。','拉丁和希伯来语接受中形成不同的阿维罗伊主义，读者的议题并不总与原作者完全相同。','1180—1198年表示成熟阶段，不能把每部评注都记为1180年完成；所谓“双重真理”也不能直接当作作者本人自称的学说。',[sep('ibn-rushd','伊本·鲁世德')],end=1198)
 event('maimonides',1190,'迈蒙尼德《迷途指津》','福斯塔特、开罗',(31.24,30.01),'摩西·迈蒙尼德','哲学与思想','犹太经文解释在伊斯兰世界的阿拉伯语哲学环境中展开，作者要处理读者在经典与理性之间感到的困难。','《迷途指津》以犹太—阿拉伯语写作，讨论神的属性、创造、预言及律法等问题，运用并批判哲学资源。','后来的希伯来语和拉丁语阅读继续改变其影响场域；中世纪思想史不能只有穆斯林与基督徒两个整齐分开的格子。','约1190年前后为常见完成范围，作品面向特定读者并有隐晦表达策略，不能仅用摘句概括全书的最终立场。',[sep('maimonides','迈蒙尼德')])
 event('university',1215,'巴黎的课程与亚里士多德准入争论','巴黎',(2.35,48.86),'教师、学生、教会权威','教育与制度','学校形成的教师学生组织，需要处理任教资格、课程、学位与纪律。所谓大学从一开始就不是现代大学的全部制度。','1215年相关章程与课程安排显示亚里士多德著作进入拉丁教学时的选择、限制及争议，不是所有作品同时自由进入课程。','大学、修院和宫廷构成不同知识环境。思想内容与机构规则共同影响哪些书可以读、如何解释。','1210、1215、1231等安排属于不同节点，不能归为一项没有变化的永远禁令，也不把它们当作希腊思想整体已被抹除。',[src('巴黎大学早期章程','https://sourcebooks.web.fordham.edu/source/uparis-statutes.asp','十三世纪课程与组织文件','中世纪文书旧英译'),medieval])
 event('condemnation',1277,'巴黎的谴责与哲学问题的边界','巴黎',(2.35,48.86),'唐皮耶、神学与哲学教师','哲学与思想','大学中的亚里士多德阅读、理智和世界问题引出不同解释；教会权威与教师共同参与界定可接受的立场。','1277年巴黎对一组命题的谴责影响相关讨论，同时不能代表所有拉丁学校或所有亚里士多德主义者的共同态度。','它既反映约束，也促使一些问题以新的方式提出；不能直接把现代科学说成由一次禁令单独造成。','应核对被谴责命题、具体作者和实际执行。“经院哲学始终统一且停滞”的说法同样掩盖了内部争论。',[sep('condemnation','1277年的谴责'),renarist])
 event('dante',1321,'但丁《神曲》：诗、政治与宇宙秩序','意大利诸城、拉文纳',(12.20,44.42),'但丁','文学与人文','放逐、城邦政治、古典诗歌和基督徒来世想象共同构成但丁写作背景。作品不能只按现代的宗教或文学二分理解。','《神曲》用俗语诗歌组织旅程、人物判断和知识世界，把古典作者、当代政治与神学放在同一文学空间。','它影响后世语言和艺术，也说明所谓中世纪与文艺复兴之间不是所有领域在同一天发生断裂。','约1321年与作品后期及作者去世相关，各部写作跨越多年；诗中人物发言和判定并不等于一份中立历史档案。',[src('普林斯顿但丁项目','https://dante.princeton.edu/','《神曲》原文、译文与注释','大学原典与研究项目')])
 event('petrarch',1341,'彼特拉克加冕与古典文学声望','罗马',(12.48,41.90),'彼特拉克、赞助者与读者','文学与人文','古典拉丁文本、写信、收藏和个人声望参与新的士人文化，政治与教会网络为文学活动提供多种空间。','彼特拉克在罗马接受桂冠诗人加冕，其阅读和著述将古代作者视为可以持续交谈的对象，而不是只作引用权威。','人文主义逐渐强调语法、修辞、诗、历史和道德教育，但这不等于所有参与者抛弃基督信仰或一切经院研究。','1341年是明确的声望事件，不能称为文艺复兴在某日正式开始；思想与文学变化早于并晚于这一节点。',[human,src('哲学百科：文艺复兴哲学','https://iep.utm.edu/renaissa/','彼特拉克与人文主义的道德及教育关怀','学术百科')])
 event('decameron',1353,'薄伽丘《十日谈》与城市叙事','佛罗伦萨',(11.26,43.77),'薄伽丘、城市读者','文学与人文','瘟疫、城市生活、商业和不同社会身份构成故事的经验背景，叙事也会利用反讽、框架和虚构人物。','《十日谈》以故事讲述群体组织多重声音，把爱情、机智、财富与宗教人员的行为置入具体情境。','俗语文学扩大了可用的文体与人物类型；对教士的讽刺不必直接等同于作者否定所有宗教信仰。','约1349—1353年为常用写作范围，此处列1353作完成约年。故事不是可以不经核对就统计社会行为的记录。',[src('布朗大学：Decameron Web','https://www.brown.edu/Departments/Italian_Studies/dweb/','文本、历史语境与研究资料','大学原典研究项目')])
 event('chrysoloras',1397,'克里索洛拉斯在佛罗伦萨教希腊语','佛罗伦萨',(11.26,43.77),'曼努埃尔·克里索洛拉斯、学生与邀请者','教育与制度','意大利已有古典阅读和希腊语学习，新的教师与手稿往来扩大了学习条件，并不是1453年以前一片空白。','克里索洛拉斯受邀教学，帮助读者直接接近希腊著作，语言训练、文法和师生网络参与了后来的翻译工作。','从文本目录、手稿和书信观察这些联系，比只讲一次城陷导致知识突然出现更能说明长期过程。','1397年为到佛罗伦萨教学的节点；其学生与后来作者的贡献不同，不能将全部文艺复兴都归于一位教师。',[human,src('英国学术院：佛罗伦萨与大分裂','https://www.thebritishacademy.ac.uk/documents/2387/75p291.pdf','1397年到佛罗伦萨及教学联系','学术研究')])
 event('dome',1420,'佛罗伦萨穹顶：设计与集体建造','佛罗伦萨',(11.26,43.77),'布鲁内莱斯基、工匠与赞助机构','艺术与建筑','教堂、城市竞争、行会和工程资源共同塑造建筑项目。艺术史不能只留下设计者而忽略工人和机构。','圣母百花大教堂穹顶从1420年展开建造，工程方法、模型和施工组织逐步解决大型空间的技术问题。','古典建筑研究与新的实践结合，并非对古罗马建筑作未经改变的复制；同城的宗教、政治和商业生活也参与成果的使用。','1420—1436年表示主要施工过程，灯亭及后续工程另有年代，不能把今天整座建筑都标成1420年完工。',[arch],end=1436)
 event('florence1439',1439,'希腊学者与佛罗伦萨的思想接触','佛罗伦萨',(11.26,43.77),'普莱通、贝萨里翁、拉丁学者','哲学与思想','东西教会的合一会议伴随使团、语言和手稿往来，宗教协商与哲学阅读有交集，却不是同一个目标。','普莱通等希腊学者的讨论以及贝萨里翁后来的活动，参与意大利读者关于柏拉图和亚里士多德的争论。','这些接触是长期希腊语教育和文本往来的一个节点，不能归纳为意大利此前从未接触任何古典哲学。','1439年对应会议阶段，相关辩论文献和收藏在后续多年发展；合一文件的接受与哲学影响也有不同历史。',[ficino,human])
 event('valla',1440,'瓦拉分析《君士坦丁赠礼》的文本','意大利、那不勒斯',(14.27,40.85),'洛伦佐·瓦拉','文学与人文','文书可以被用来支持制度和权力主张，人文主义的语言训练又使词汇、文体及时代语境成为批判材料的工具。','瓦拉指出《君士坦丁赠礼》的语言和历史环境与声称的古代来源不合，用语文学论证挑战其真实性。','这一方法联系文献、政治与宗教争论，后来也影响其他文本研究；批判文书不等于否认所有传统或全部教会制度。','约1440年为写作节点，公开印行与接受有更晚历史；不要把手稿传播和现代出版意义的即时公开等同。',[human,sep('lorenzo-valla','洛伦佐·瓦拉')])
 event('ficino-plato',1484,'费奇诺的柏拉图拉丁文集刊行','佛罗伦萨',(11.26,43.77),'马尔西利奥·费奇诺、抄写与印刷协作者','哲学与思想','古典手稿、希腊语学习、赞助和印刷共同扩大阅读条件。费奇诺同时以基督徒身份理解柏拉图传统。','1484年刊行的柏拉图拉丁译集为拉丁读者接触作品全貌提供重要资源，翻译与注释也带入译者自己的理解。','柏拉图主义与亚里士多德主义仍长期并行竞争，不能说某一年一本书完全取代了所有大学课程。','此年为印本刊行节点，翻译此前已持续多年；“柏拉图学院”的具体制度和后世浪漫化形象也须区别。',[ficino,renarist])
 event('pico',1486,'皮科的九百论题与人的可能性','罗马、佛罗伦萨',(12.48,41.90),'皮科·德拉·米兰多拉','哲学与思想','年轻学者在不同哲学、神学和语言传统之间寻求论辩，个人抱负与教会审查的条件同时存在。','皮科提出九百论题并准备相关演说，讨论不同传统如何比较、协调及辩难，随后面对审查与争议。','后世把《论人的尊严》视为文艺复兴的象征，但作者同时关注神学、修养和多种传统，并非现代个人主义的简短宣言。','1486年是论题准备和出版阶段；拟议公开论辩并未按计划举行，演说不能当成当时已向全城公开宣读的现场记录。',[pico])
 event('ficino-plotinus',1492,'普罗提诺的拉丁译本与注释刊行','佛罗伦萨',(11.26,43.77),'费奇诺、普罗提诺的后世读者','文本与科技','阅读柏拉图的方式也受到晚期古代注释者影响，拉丁译者借翻译、评注和教学组织不同作者之间的关系。','费奇诺的普罗提诺译注刊行，扩大拉丁读者接触《九章集》及相关灵魂、理智和太一问题的条件。','这是一层新的接受史，不等于前四世纪柏拉图自己已经写出了普罗提诺的全部体系，也不能把费奇诺的解释自动当作原作者唯一含义。','1492年是译注印本节点；原作、波菲利编排、十五世纪译注和现代译本属于四个不同层次。',[ficino,plotinus])
 event('aldine',1495,'阿尔杜斯与希腊文印刷','威尼斯',(12.34,45.44),'阿尔杜斯·马努提乌斯、希腊语编校者','文本与科技','威尼斯的贸易、纸张、字体和流动学者支持新的出版项目。印刷仍需要校勘、语言能力与经济资源。','阿尔杜斯的希腊文亚里士多德等出版项目，帮助读者接触原文并比较译本，编校和排字劳动共同塑造印本。','印刷扩大流通，也可能固定错误；它没有让手稿和大学注释立即消失，读者接触的版本仍有差别。','1495—1498年对应亚里士多德希腊文集的重要出版阶段，不是所有希腊古籍在1495年第一次被印出。',[src('国会图书馆：人文主义与古典印本','https://www.loc.gov/exhibits/vatican/humanism.html','古典文本与人文主义的印刷传播','馆藏研究'),renarist],end=1498)
 event('athens-school',1509,'拉斐尔《雅典学园》：文艺复兴如何想象古人','罗马、梵蒂冈',(12.45,41.90),'拉斐尔、教廷赞助者与工坊','艺术与建筑','文艺复兴的图像可以用古典人物组织当代的知识理想，作品又处在教廷建筑、赞助与工坊协作中。','《雅典学园》把哲学家置于理想化建筑空间，后世常以柏拉图和亚里士多德的姿态解释不同求知方式。','这是一件关于古典哲学的十六世纪再现，不是古代学校的写生合影；人物辨认中的确定和推测应分别标注。','约1509—1511年为壁画制作阶段，古人衣着和建筑不能直接当作前四世纪现场证据。作品保存与修复又有后来的历史。',[src('梵蒂冈博物馆：签字厅','https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/stanze-di-raffaello/stanza-della-segnatura.html','《雅典学园》及室内图像安排','馆藏作品说明')],end=1511,image='school-athens')
 event('prince',1513,'马基雅维利《君主论》的写作','佛罗伦萨及周边',(11.26,43.77),'尼科洛·马基雅维利','文学与人文','意大利城邦竞争、外交、战争与个人政治失势构成写作处境，古代史例被用来分析具体权力问题。','《君主论》讨论统治、军队、时运及行动判断，借历史与经验提出尖锐问题；其修辞、目的和与其他作品的关系仍有讨论。','把政治论证放回作者的共和国经验和其他著作，可避免只用“权谋无道德”一句话概括全部思想。','1513年突出写作阶段，印本到1532年才出现。后世“马基雅维利主义”标签也不能代替逐章阅读原文。',[sep('machiavelli','马基雅维利')])
 event('erasmus',1516,'伊拉斯谟的新约、注释与人文主义语文学','巴塞尔',(7.59,47.56),'伊拉斯谟、印刷者与读者','文学与人文','古典语言训练和基督徒改革关怀相遇，使手稿、翻译和注释进入公共争论。出版依赖可取得的具体版本。','伊拉斯谟的新约希腊文、拉丁文和注释出版，邀请读者比较词义和解释；这是重要成果，也带有手稿条件与编辑选择的限制。','语文学既可服务宗教实践，也引发权威争论。人文主义和宗教改革不是完全相同的运动，参与者的立场与后续道路有差异。','1516年是首版节点，后续多次修订；不能把首版等同于今日拥有全部手稿资源的现代批判校勘本。',[erasmus,src('剑桥王后学院：伊拉斯谟新约','https://www.queensoldlibrary.org/Exhibitions/Erasmus-exhibition/Erasmus-Testament','1516年版本与馆藏','馆藏研究')],links=['world-047'])
 event('vives',1526,'维韦斯与城市贫困救助','布鲁日',(3.22,51.21),'胡安·路易斯·维韦斯、城市居民与官员','教育与制度','城市贫困、流动人口与救助资源促使人文主义作者把道德教育和制度安排联系起来，而非只谈古典文体。','《论救济穷人》讨论城市如何了解需要、安排援助与劳动，体现人文主义在社会实践中的一条线索。','与教会慈善、城市治理和中国救荒材料比较时，应辨认权利、纪律、资源和具体对象，不用一种现代福利制度替代其全部语境。','1526年是著作刊行节点，建议并不表示所有城市当年已实施，规范文本与实际生活还需其他材料。',[sep('vives','胡安·路易斯·维韦斯')])
 event('courtier',1528,'《廷臣论》与宫廷教育理想','乌尔比诺、威尼斯',(12.64,43.73),'卡斯蒂廖内、宫廷男女与读者','文学与人文','宫廷社交、礼仪、艺术与政治服务构成精英教育环境，其可用资源及评价标准与大多数居民不同。','《廷臣论》借对话讨论语言、风度、才艺与判断，也让不同人物提出并争论理想行为，而非只有一条统一命令。','作品影响欧洲精英文化，但不能把书中的修养理想直接当作所有男女的现实生活；宫廷之外还有多种知识与劳动。','1528年为刊行年，设定中的对话时间与实际写作、修订时间不同。角色声音与作者立场亦需区分。',[src('大都会博物馆：文艺复兴教育材料','https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf','人文主义、宫廷与艺术的研究入口','博物馆教学材料')])
 event('copernicus',1543,'哥白尼《天体运行论》刊行','纽伦堡、弗龙堡',(11.08,49.45),'哥白尼、雷蒂库斯、奥西安德','科学与知识','古代天文学、数学模型、观测与计算长期积累，宇宙秩序的讨论又涉及哲学和经文解释。','《天体运行论》提出以地球运动为核心的体系，出版过程中还出现不具作者署名的读者序言等问题。','新的模型并非立刻获得普遍接受，后来的观测、物理与数学论证继续改变争论，不能用一位作者一年完成现代科学的故事概括。','1543年为出版年，不是作者首次提出所有思想之年；印本序言、正文的主张及后世的证明标准应分别读。',[sep('copernicus','哥白尼')],image='copernicus-book')
 event('vesalius',1543,'维萨里《人体的构造》与解剖图像','巴塞尔、帕多瓦',(7.59,47.56),'安德烈亚斯·维萨里、绘图者与印工','科学与知识','医学教学借文本、人体、演示和图像组织知识，古代权威在实践中被检验并重新解释。','《人体的构造》把详细图像与解剖论述相连，挑战部分传统描述；书的视觉和学术成果依赖多种专业劳动。','与同时年的哥白尼著作并置，可讨论知识呈现和证据标准，但二者领域、方法及接受史并不相同。','1543年为首版，1555年另有重要修订；图像是经过选择和制作的表现，不是无中介的现代摄影。',[src('美国国家医学图书馆：Vesalius','https://www.nlm.nih.gov/exhibition/historicalanatomies/vesalius_home.html','《人体的构造》及图版','馆藏医学史实物')])
 event('vasari',1568,'瓦萨里的艺术家传记与艺术史叙述','佛罗伦萨',(11.26,43.77),'乔尔乔·瓦萨里、艺术家与赞助人','艺术与建筑','艺术家声望、城市竞争与赞助关系影响作品如何被评价和保存，传记把个人故事与风格变化组织为可讲述的历史。','《艺苑名人传》的扩充版本重写和增加人物，把艺术发展描述为具有阶段和高峰的过程。','这一叙述对艺术史影响深远，也有地域偏好与文学安排；文艺复兴并非只有托斯卡纳一条成就线。','1568年为第二版节点，首版1550年。传记中的轶事、评价和可核对的合同、作品年代需要分别辨认。',[src('瓦萨里《艺苑名人传》选篇','https://sourcebooks.web.fordham.edu/basis/vasari/vasari-lives.asp','艺术家传记与作者叙述的旧英译本目录','近代原典旧英译')])
 event('montaigne',1580,'蒙田《随笔》：自我检视与判断的限度','波尔多及蒙田城堡',(-0.58,44.84),'米歇尔·德·蒙田','哲学与思想','古代阅读、宗教战争、地方政治和个人生活经验，在一种不求固定教科书体系的写作中相遇。','《随笔》借题发挥，反思习俗、教育、友谊和判断的局限，作者也在后续版本中不断增订。','古代怀疑论在这里被重新使用，却不能简单等同于否认一切信仰或一切知识；自我写作同样经过修辞组织。','1580年为首版，不是所有通行篇章均在当年已有。后来的增订及死后版本应按文本层次辨认。',[sep('montaigne','蒙田')])
 event('bacon1605',1605,'培根《学术的进展》与知识组织','伦敦',(-0.13,51.51),'弗兰西斯·培根','科学与知识','宫廷、法律、大学与技术实践提供不同知识场域。改革知识不仅关系结论，也涉及教育和组织资源。','《学术的进展》检视知识分类、研究目标与不足，尝试为新的求知工作争取位置，不是把所有古代著作简单丢弃。','人文修辞、历史经验和自然研究在这一工作中互相联系，所谓科学革命与文艺复兴之间也存在交织。','1605年为英语著作刊行年，后来的拉丁扩充和其他计划另有年代，不能把一书当成已经实施的完整科研制度。',[sep('francis-bacon','弗兰西斯·培根')])
 event('bacon1620',1620,'《新工具》与经验、偏见和归纳','伦敦',(-0.13,51.51),'弗兰西斯·培根','科学与知识','培根针对既有求知方式提出批评，也反思语言、习惯、个人判断和权威可能如何妨碍研究。','《新工具》讨论偶像和归纳等问题，主张重新组织观察、实验与推理的关系，其计划并非今日一套简单的实验步骤。','与亚里士多德逻辑及其他近代方法比较，能看到连续与分歧；不能仅用经验主义对理性主义的标签代替具体论证。','1620年为刊行节点，作者的庞大改革计划并未全完成，思想影响也与后来的读者和机构有关。',[sep('francis-bacon','弗兰西斯·培根')])
 event('galileo',1632,'伽利略《对话》与宇宙体系争论','佛罗伦萨',(11.26,43.77),'伽利略、出版审查者与读者','科学与知识','观测、数学、自然哲学和经文解释在不同制度中争论，出版许可与宫廷支持也影响作品的处境。','《关于两大世界体系的对话》用角色对谈比较体系和证据，随后1633年的审判成为另一重要事件。','论证内容、书的修辞及权力程序均应阅读；不能把全部教会、全部学者或全部科学立场化约成两个完全一致阵营。','1632年出版与1633年审判分开。作品的某些物理解释后来并不成立，其历史价值不等于每一项论证都被现代科学接受。',[src('伽利略博物馆：《对话》','https://www2.museogalileo.it/it/biblioteca-e-istituto-di-ricerca/progetti/incontra-galileo/31-opere/460-dialogo-sopra-i-due-massimi-sistemi-del-mondo-1632.html','1632年出版及文体、审查和论证','馆藏与学术研究')])
 event('descartes',1637,'笛卡尔《方法谈》与知识重建','莱顿',(4.50,52.16),'勒内·笛卡尔','哲学与思想','数学、机械论、教育经历和哲学怀疑构成早期近代知识重建的条件，并非文艺复兴传统一夜消失。','《方法谈》与相关科学论文一同刊行，以法语叙述求知经历与方法，探索何种判断可以构成可靠知识。','它与古代怀疑传统有联系又有不同目标；方法、形而上学和具体科学研究之间的关系需要看各篇作品。','1637年为刊行节点，不是所有后来笛卡尔学说的最终版本；1641年《沉思》及1644年《哲学原理》另有发展。',[sep('descartes','笛卡尔')])
 event('primavera',1482,'波提切利《春》与古典神话的再组织','佛罗伦萨',(11.26,43.77),'桑德罗·波提切利、赞助者与工坊','艺术与建筑','古典神话、诗歌、婚姻和精英赞助在佛罗伦萨图像文化中交织，画家选择和组合不同视觉资源。','《春》把神话人物安排在精细的花木空间中，展示古典题材怎样进入十五世纪的审美和社会表达。','它与宗教艺术并行，而不是证明画家或整个城市已不再信仰基督宗教；画面解释还涉及赞助与观看条件。','约1480年代为常见断代，此处以约1482年定位，具体委托和完整寓意仍有讨论，不把一种解释标成唯一确证。',[src('乌菲齐：《春》','https://www.uffizi.it/en/artworks/botticelli-spring','作品、断代与神话人物','馆藏作品说明')],image='primavera')
 event('vitruvian',1490,'列奥纳多《维特鲁威人》：身体、几何与古典文本','威尼斯、意大利诸城',(12.34,45.44),'列奥纳多·达·芬奇、维特鲁威的读者','艺术与建筑','古代建筑文本提供人体比例与空间秩序的论题，文艺复兴读者以测量、绘图和观察重新处理这些材料。','这幅素描把人体、圆和方形联系起来，并附有文字，显示图像、古典阅读与研究手稿之间的关系。','它是一次具体的研究表达，不是所有人体都服从同一理想比例的现代统计结论；列奥纳多的观察也并非与工坊劳动无关。','约1490年为常用断代；今天保存于威尼斯不等于作品一定在该城完成。文化点位标馆藏关联城市，不能当作已确证的作画门址。',[src('威尼斯学院美术馆：Vitruvian Man','https://www.gallerieaccademia.it/en/study-proportions-human-body-known-vitruvian-man','手稿、比例与作品断代','馆藏作品说明')],image='vitruvian')
 event('david',1504,'米开朗琪罗《大卫》与佛罗伦萨公共空间','佛罗伦萨',(11.26,43.77),'米开朗琪罗、委托机构与城市观众','艺术与建筑','圣经人物进入城市政治和艺术委托，材料、原定位置与后来实际陈列共同改变作品意义。','完成于1504年前后的《大卫》以古典人体和巨大尺度重新表现圣经人物，进入佛罗伦萨公共生活。','同一作品可以同时拥有圣经、审美和城市象征层次；不能只用世俗或宗教一个标签覆盖全部用途。','1501—1504年为主要制作阶段，今天博物馆内的原作与广场上的复制品要分别辨认。',[src('佛罗伦萨学院美术馆：David','https://www.galleriaaccademiafirenze.it/en/artworks/david-michelangelo/','制作、委托与陈列','馆藏作品说明')])
 event('sistine',1508,'西斯廷礼拜堂天顶画工程','罗马、梵蒂冈',(12.45,41.90),'米开朗琪罗、教廷赞助者与协作者','艺术与建筑','教廷赞助、礼仪空间和圣经解释塑造大型艺术项目。工程依赖脚手架、材料与长时间的身体和技术劳动。','1508—1512年的天顶画工程把创世、人物和救恩相关主题组织在建筑空间中，艺术表现与观看位置密切相关。','《创造亚当》等局部后来成为独立图标，但原先属于整体程序；观看复制品的经验不等于礼拜堂中的实际空间。','1512年关联工程揭幕，《最后的审判》则是后来另一时期的作品。不要把天顶全部画面标成1508年同一天画成。',[src('梵蒂冈博物馆：天顶','https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/cappella-sistina/volta.html','1508—1512年天顶画与整体图像程序','馆藏作品说明')],end=1512,image='creation-adam')
 def tradition(id,span,title,names,a,b,c,d,refs,related):
  traditions.append(dict(id='tradition-'+id,range=span,title=title,people=names.split('、'),sections=sections(a,b,c,d),sources=refs,eventIds=[],relatedCultureIds=['culture-'+v for v in related],kind='思想传统导读；跨年代回顾，不是一条无分歧的师承线'))
 tradition('nature',[-600,-400],'自然、存在与变化','米利都思想者、赫拉克利特、巴门尼德、原子论者','最早期材料提出世界根源、变化与可靠知识的问题，但“前苏格拉底”本身是后世分类，并不意味着这些作者完全不讨论人的生活。','单一根源、存在的论证和多元构成方案互相回应；变化能否得到解释，感觉与思想有何关系，是持续的核心问题。','后来柏拉图和亚里士多德既吸收也批评前人的问题。现代自然科学与这些论辩有历史关系，却有不同方法、工具与制度。','从原著残篇、后世引述和现代重建三层阅读，避免把一句名言当作一套完整系统，或假定所有影响方向均已确定。',[pre],['greek-roman','philoponus'])
 tradition('plato',[-470,600],'苏格拉底、柏拉图与晚期柏拉图传统','苏格拉底、柏拉图、普罗提诺、波菲利','从如何生活、何为知识与正义，到理智、灵魂及最高原则，问题在不同语境和文体中发生变化。','对话、学校教学和后来的系统化注释是不同实践；柏拉图、普罗提诺及其继承者并非只是换了名字的同一个人。','拉丁基督徒、希腊语及阿拉伯语读者重新提出这些问题，费奇诺又借翻译建立自己的古典与信仰关系。','“理念”“太一”“逻各斯”等不能随意互换。源头、后来的柏拉图主义和文艺复兴接受必须分别说明。',[plato,plotinus],['plotinus','enneads','augustine-platonists','ficino-plato','ficino-plotinus'])
 tradition('aristotle',[-384,1600],'亚里士多德：逻辑、自然与实践的多种读法','亚里士多德、注释者、翻译者与大学教师','亚里士多德将不同研究领域组织成问题、分类与论证，但现存文本有教学、编辑和传抄的层次。','原因、实体、德性、幸福、城邦和诗的表现并不在所有领域使用相同标准；实践智慧也不是机械套用公式。','古希腊、拜占庭、阿拉伯语、希伯来语和拉丁世界形成不同解释，文艺复兴的亚里士多德主义仍然活跃。','不能把他视为中世纪只有一套答案的单一权威，也不能说文艺复兴靠柏拉图一次性消灭了全部亚里士多德研究。',[arist,ethics,renarist],['philoponus','avicenna','averroes','university','condemnation','aldine'])
 tradition('hellenistic',[-306,200],'希腊化学派：幸福、判断与共同生活','伊壁鸠鲁、芝诺、学园怀疑论者、爱比克泰德','希腊化及罗马时代的哲学关心如何认识和怎样生活，学派常有共同体、书信、教育与日常训练。','伊壁鸠鲁传统强调审慎、友谊及免除扰乱；斯多亚把德性、判断和宇宙秩序相连；怀疑传统检视判断的根据。','这些立场在新约时代仍有听众，后来的基督徒作者既批评也选择借用资源，但各人的回应并不一致。','不要把伊壁鸠鲁主义说成纵欲、斯多亚说成压抑全部感受、怀疑论说成什么也不相信；应读作者提出的理由和实践。',[epic,stoic,sceptic],['areopagus','seneca','epictetus','marcus','montaigne'])
 tradition('translation',[750,1300],'跨语言的哲学：希腊语、叙利亚语、阿拉伯语、希伯来语、拉丁语','译者、肯迪、伊本·西那、伊本·鲁世德、迈蒙尼德','思想跨语言传播需要手稿、语言能力、赞助和有问题意识的读者。词义、文体和学校制度会影响可译与可理解的内容。','翻译、注释和新的论证同时进行。阿拉伯语哲学和犹太哲学拥有自己的创造，不能只被当作希腊思想去往拉丁欧洲的被动中站。','多个地方和时期的拉丁翻译改变教学，也与直接读希腊文本的通道并行；拜占庭保存和发展古典知识的工作从未缺席。','“东方保存、西方重获”的单线故事不足以解释材料，具体作品如何被改写、署名、阅读与争论更有解释力。',[arabic,latin],['translations','kindi','avicenna','averroes','maimonides','toledo'])
 tradition('schools',[1100,1550],'学校、大学与经院论证','阿伯拉尔、阿奎那、哲学和神学教师','课程、学位、修会和教会制度共同塑造知识生产。学校中的问题讨论也会与宫廷、城市及手工业知识交往。','提问、反对理由、权威引用和回答构成常见的论证组织；自然哲学、逻辑和神学有区别，也彼此发生争议。','人文主义后来改变文本、教育和文体的优先次序，但经院研究并未消失，两种实践也可能在同一位作者身上相遇。','经院不是一个从来没有争论的死板体系。应把课程限制、具体论敌和作者修订放回实际年代。',[medieval,renarist],['abelard','university','condemnation','valla','erasmus'])
 tradition('humanism',[1300,1600],'人文主义：语言、历史、教育和行动','彼特拉克、瓦拉、费奇诺、皮科、伊拉斯谟、维韦斯','人文主义首先联系古典语言和一组教育实践，不只是现代意义上以人为中心的世界观，也不是所有人共同接受的一套哲学。','文本校勘、修辞、历史与道德教育，参与宗教解释、外交、城市治理和个人修养，作者之间却有不同取向与矛盾。','文艺复兴既出现古典神话艺术，也产生大量基督教图像与研究。宗教、人文、技术和赞助常常互相交织。','不要用中世纪黑暗对文艺复兴觉醒的二分替代研究；拜占庭、阿拉伯语和中世纪拉丁传统均参与前提条件。',[human,ficino,erasmus],['petrarch','chrysoloras','valla','ficino-plato','pico','erasmus','vives'])
 tradition('arts',[1400,1648],'艺术、身体与新的求知方式','工坊、布鲁内莱斯基、列奥纳多、米开朗琪罗、拉斐尔、近代作者','建筑、绘画、测量、解剖和印刷依赖手、眼、文本和组织资源。艺术家形象的上升并没有使集体劳动消失。','透视、人体研究和古典图像重组，与观测、数学和自然哲学既相遇也有各自标准；不是所有成果出自同一方法。','十六、十七世纪知识改革在延续和批评传统中发展，现代学科分工不能原样套回工坊、宫廷和大学。','作品的制作年代、后来陈列、复制图和现代解释要分别标注；可以比较图像和科学论证，不能凭视觉相似就证明因果。',[arch,renarist],['dome','primavera','vitruvian','david','sistine','athens-school','copernicus','vesalius','galileo','descartes'])
 # Biographies link to their cultural dossiers as well as the main church chronology.
 def person(id,name,life,span,role,a,b,c,refs,links):
  data['people'].append(dict(id=id,side='west',name=name,lifeLabel=life,activeRange=span,role=role,sections=[dict(title='人物与问题',text=a),dict(title='作品与历史作用',text=b),dict(title='阅读辨析',text=c)],sources=refs,eventIds=[],cultureIds=['culture-'+v for v in links]))
 person('socrates','苏格拉底','约前469—前399',[-450,-399],'雅典哲学讨论者','苏格拉底通过对话追问德性、知识和怎样生活，活动处在雅典城邦具体的政治与教育环境中。','他没有留下自己的著作，柏拉图、色诺芬与喜剧作者保存并塑造不同的苏格拉底，后继者再以不同方式发展其问题。','区分历史人物、作品中的角色与后世哲学象征，不以一句未经审辨的格言替代现存证词。',[apology,socr],[])
 person('plato','柏拉图','约前428/427—前348/347',[-387,-347],'哲学对话作者；学园传统人物','柏拉图把知识、善、灵魂和政治置于精心组织的对话中。作品中的提问、神话和角色声调同样参与论证。','他的影响经后来的学校、译者、教会作者与文艺复兴读者不断重构，不能只用理念二字概括所有作品。','学园年代有约略性，后世雕像与《雅典学园》均不是其本人在世时的照片或现场记录。',[plato],['ficino-plato','athens-school'])
 person('aristotle','亚里士多德','前384—前322',[-367,-322],'哲学研究者；吕克昂教学传统人物','他在学园及其他地区学习和工作，研究从逻辑、生物到伦理、政治和诗，不是只给柏拉图作一个反面答案。','现存材料经编辑和传抄形成不同著作，后来的注释、翻译和课程改变其用途，也激发新的批评。','逻辑、自然和实践领域不使用完全相同的论证标准；后世亚里士多德主义内部亦有分歧。',[arist,ethics],['avicenna','averroes','university','aldine'])
 person('epicurus','伊壁鸠鲁','前341—前270',[-306,-270],'花园学派人物','伊壁鸠鲁将自然解释、消除恐惧和日常生活联系起来，友谊与审慎选择欲望具有重要地位。','书信及其他保存材料说明他如何理解快乐、死亡和神，后世读者通过不同来源接触这些观点。','不要把快乐简化为追求刺激，也不因其与某些神学不同，就认定其伦理没有自我约束和对友人的责任。',[epic],['areopagus'])
 person('zeno-stoa','基提翁的芝诺','约前334—前262',[-300,-262],'早期斯多亚学派人物','这里指斯多亚传统的芝诺，不是提出著名悖论的埃利亚芝诺。两个同名人物相隔时代与问题。','他在雅典形成教学联系，后继者发展逻辑、自然与伦理研究，后来罗马作者又以新文体重述部分问题。','许多早期著作已失，应区分创始者、克律西波及罗马斯多亚的各层材料，不用现代性格标签代替学派。',[stoic],['seneca','epictetus','marcus'])
 person('plotinus','普罗提诺','约204/205—270',[244,270],'晚期柏拉图主义哲学家','普罗提诺从不同求学经历进入罗马教学网络，围绕柏拉图传统及其他作者提出自己的系统性问题。','太一、理智、灵魂与归返是重要线索，波菲利编订的《九章集》则塑造后世阅读作品的顺序。','他不等于柏拉图本人，也不能把所有受其影响的基督徒作者都说成接受了同一套完整哲学。',[plotinus],['plotinus','enneads','ficino-plotinus'])
 person('kindi','肯迪','约九世纪初—九世纪后半叶',[830,870],'阿拉伯语哲学家与知识组织者','肯迪及其圈子在翻译和多学科研究中提出问题，活动依赖语言协作与赞助环境，而非孤立地保存古典文本。','其工作联系形而上学、数学及其他知识，展现阿拉伯语作者对不同希腊资源的组织和创造。','不将其全部著述归给同一年，也不把阿拉伯语哲学仅称为欧洲思想史的被动过渡。',[sep('al-kindi','肯迪')],['kindi','translations'])
 person('avicenna','伊本·西那','980—1037',[1020,1037],'哲学家、医师与著述者','伊本·西那在多个政治中心活动，自己的论证将逻辑、自然、灵魂与形而上学组织为相互关联的问题。','《治疗论》等作品后来进入不同语言传统，对存在和认识的讨论产生广泛影响；医学著述又是另一组工作。','“阿维森纳”是常见拉丁译名，不表示他是欧洲出生的作者；《治疗论》也不能只凭题名归作医学。',[sep('ibn-sina','伊本·西那')],['avicenna'])
 person('averroes','伊本·鲁世德','1126—1198',[1170,1198],'安达卢斯哲学家、法学家与医师','他的亚里士多德阅读形成于具体的法律、宗教与知识环境，短、中、长评注具有不同目的。','后来的拉丁与希伯来读者将这些论证带入自己的争议，所谓阿维罗伊主义因此不是一个完全相同的群体。','不能把“双重真理”直接当作他的自我主张，也不因其评注古人便略去自己的哲学论证。',[sep('ibn-rushd','伊本·鲁世德')],['averroes'])
 person('maimonides','迈蒙尼德','1138—1204',[1190,1204],'犹太哲学家、法学家与医师','迈蒙尼德借犹太—阿拉伯语写作回应经文、哲学与生活问题，活动与地中海跨地区网络有关。','《迷途指津》和律法著述属于不同文体，译本及解释又让其进入更广的犹太和拉丁学术讨论。','不能把作者的多重工作压成只在协调两套现成教义；作品的对象、隐晦表达和具体章节均需注意。',[sep('maimonides','迈蒙尼德')],['maimonides'])
 person('aquinas','托马斯·阿奎那','约1225—1274',[1265,1274],'多明我会神学家；大学教师','阿奎那在修会与大学环境中讨论经文、哲学和不同权威，工作并非将亚里士多德无条件改名为基督教。','《神学大全》、争辩问题及亚里士多德注释等著作各有目的，回应具体论敌并持续调整论证。','理性与信仰、哲学与神学的区分不是两者完全没有联系；也不将其未完成的著作视为作者亲自定稿的一切答案。',[sep('aquinas','托马斯·阿奎那')],['university','condemnation'])
 person('petrarch','彼特拉克','1304—1374',[1341,1374],'诗人、人文主义阅读与书信作者','彼特拉克通过诗、散文、书信与古典收藏塑造一种与古人交谈的自我形象，依赖具体政治和赞助网络。','其古典道德关怀与基督徒自我检视并行，后来的教育和文学传统选择性发展这些资源。','不能把他简单归作无宗教的现代个人，也不认为1341年加冕就使全欧洲在同一天进入文艺复兴。',[human,src('哲学百科：文艺复兴哲学','https://iep.utm.edu/renaissa/','彼特拉克与人文主义的道德及教育关怀','学术百科')],['petrarch'])
 person('valla','洛伦佐·瓦拉','1407—1457',[1440,1457],'语文学家；修辞和文献批判作者','瓦拉把词语、文体、历史语境与论辩联系起来，其活动又进入不同政治和教会网络。','对《君士坦丁赠礼》的分析及对拉丁语言、圣经等文本的研究，参与改变权威文书怎样被阅读。','批判个别文书不等于抛弃所有信仰，也不意味着每项历史结论都只靠一处词汇便已得到证明。',[sep('lorenzo-valla','洛伦佐·瓦拉')],['valla'])
 person('ficino','马尔西利奥·费奇诺','1433—1499',[1484,1499],'哲学家、翻译者与基督徒思想家','费奇诺在佛罗伦萨的手稿、赞助与教学联系中工作，试图把古典哲学与自己理解的宗教历史相连。','柏拉图及普罗提诺的拉丁译注扩大阅读条件，译者的选择也塑造后人对古人的理解。','不要把他称为原封不动复原柏拉图的人，也不把后世浪漫化的学院图景直接当作正式制度事实。',[ficino],['ficino-plato','ficino-plotinus'])
 person('pico','皮科·德拉·米兰多拉','1463—1494',[1486,1494],'哲学论辩者与多传统阅读者','皮科在希腊、拉丁及其他语言传统中寻找比较和协调的可能，个人计划同时面对政治与审查条件。','九百论题及相关著述讨论人的可能性、修养与知识关系，但不能与现代自由个人主义简单等同。','拟议论辩未按原计划举行，《论人的尊严》的后来名声也不是作品在1486年已经被全社会共同接受。',[pico],['pico'])
 person('erasmus','伊拉斯谟','约1466/1469—1536',[1516,1536],'人文主义学者；语文学与宗教著述作者','伊拉斯谟通过跨国书信、印刷和古典语言研究参与基督徒教育和改革，处境不能只由一个民族国家归属解释。','新约版本和注释、教育与讽刺著作属于不同工作；他与改革者有接触也有重要分歧。','不要把人文主义与新教改革视为同义词，也不将1516年初版等同于现代完备手稿条件下的最终校勘本。',[erasmus],['erasmus'])
 person('leonardo','列奥纳多·达·芬奇','1452—1519',[1490,1519],'画家、绘图与自然研究实践者','列奥纳多的活动连接工坊、宫廷、手稿和实际观察，艺术、工程和身体研究在其工作中相遇。','图像、测量与文字共同组织探究，作品及笔记后来经收藏、拆分和编辑进入现代的天才形象。','未刊笔记不能当作当时已广泛传播的发明专利，设想、模型与实际完成的器物也需分开。',[src('皇家收藏：Leonardo','https://www.rct.uk/collection/themes/trails/leonardo-da-vinci','素描、笔记与研究','馆藏实物研究')],['vitruvian'])
 person('michelangelo','米开朗琪罗','1475—1564',[1504,1564],'雕塑家、画家、建筑与诗歌实践者','他的工作处在佛罗伦萨、罗马等地的委托与政治环境中，理想化天才传记不能替代合同、材料和制作过程。','《大卫》与西斯廷天顶画以不同材料和空间处理身体、圣经人物及观看关系，均依赖长期劳动。','天顶画和《最后的审判》属于不同时期，古典人体表现也不必直接等于放弃宗教信仰。',[src('梵蒂冈博物馆：西斯廷礼拜堂','https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/cappella-sistina.html','建筑、委托及作品分期','馆藏作品说明')],['david','sistine'])
 person('christine','克里斯蒂娜·德·皮桑','约1364—约1430',[1405,1430],'作家；女性教育与政治文化讨论者','她在法国宫廷与文字生产环境中谋生和写作，对贬抑女性的文本传统提出回应，身边也有抄写、绘饰和读者网络。','《妇女城》等作品借文学和历史人物组织论辩，让教育、道德与女性能力成为公共文本问题。','不能把作品直接称为一份现代平权法律纲领，也不忽略其基督徒和宫廷文化背景；作者自己的立场仍需按作品分别阅读。',[src('大英图书馆：Christine de Pizan 研究与馆藏','https://www.bl.uk/stories/blogs/posts/christine-de-pizan-and-the-book-of-the-queen','作者主持编纂的作品集、宫廷读者与手稿制作','馆藏研究')],[])
 person('montaigne','蒙田','1533—1592',[1580,1592],'随笔作者；判断与习俗的反思者','蒙田把古代阅读、地方政治、宗教战争和自身经验放在随笔中检视，文章不是只有一个预先确定结论的体系。','反思习俗、教育、友谊与判断的限度，使古代怀疑传统在新的生活和文体中获得用途。','不同版本不断增订，不能从现代选本的一句格言直接推断其所有信仰或政治立场。',[sep('montaigne','蒙田')],['montaigne'])
 person('descartes','勒内·笛卡尔','1596—1650',[1637,1648],'哲学家；数学与自然研究作者','笛卡尔在早期近代教育、数学及自然哲学环境中重建知识问题，既继承也批评原有概念和论证。','《方法谈》等著作以不同体裁处理方法、判断和具体科学，后来的沉思与原理又有进一步发展。','本项目历史终点为1648年，小传可注明生卒但不把之后发生的事件提前放进年轴；理性主义标签也不能代替原文。',[sep('descartes','笛卡尔')],['descartes'])
 data['cultureEvents']=sorted(events,key=lambda e:(e['year'],e['id']))
 data['culturePrehistory']=early
 data['cultureTraditions']=traditions
 data['worldEvents'].extend(events)
 # Standalone phase introductions are visible on the map's narrative column.
 rows=[(30,199,'希腊哲学在罗马世界','古典学派在新约时代仍然活跃。城市教育、犹太经文解释和基督徒群体，以不同方式处理神、世界、德性与复活等问题。'),(200,599,'晚期古代：注释、信仰与哲学','柏拉图传统、亚里士多德注释和基督徒作者相互讨论。文本编辑、教学与政治限制共同改变知识环境，哲学并未在一个年份整体终止。'),(600,1099,'多语言的知识网络','拜占庭的希腊语传统与叙利亚语、阿拉伯语翻译和著述并行发展。译者、医师、宗教群体与赞助者共同参与，思想也在传播中被创造性改写。'),(1100,1299,'翻译、大学与经院争论','拉丁和希伯来语读者通过多条途径接触古典与阿拉伯语著作。大学课程、神学、法律和哲学争论形成新的知识条件。'),(1300,1399,'诗歌、古典阅读与人文教育','但丁、彼特拉克和薄伽丘等作者改变语言、历史和自我表达的方式。文艺复兴的前提是长期形成的网络，不是中世纪在某日突然结束。'),(1400,1452,'语文学、建筑与古典再阅读','文本批判、希腊语学习、建筑实践与赞助关系交织发展。古典资源被重新解释，而非没有选择地复制。'),(1453,1516,'翻译、印刷与文艺复兴艺术','费奇诺、皮科及多种大学传统并行，威尼斯印刷和大型艺术委托扩展了传播。1453年不是希腊思想第一次进入意大利的起点。'),(1517,1599,'多条人文主义与艺术路线','宫廷教育、救助、自然与人体研究、艺术家传记和随笔呈现不同的文化实践。人文主义、宗教改革和天主教更新有联系也有不同目标。'),(1600,1648,'知识改革与早期近代问题','培根、伽利略和笛卡尔从不同角度重组证据、方法和知识。新的论证延续并批评传统，不能只用理性战胜信仰的二分说明。')]
 data['cultureContexts']=[dict(range=[a,b],title=t,summary=s) for a,b,t,s in rows]
 manifest=Path(__file__).resolve().parents[1]/'dist/data/culture-images.json'
 data['cultureImages']=json.loads(manifest.read_text()) if manifest.exists() else []
 # Keep these ordinary, precisely sourced nodes reachable from both views.
 for person in data['people']:
  person.setdefault('cultureIds',[])
